require('dotenv').config();
const protobuf = require('protobufjs');

/* ==============================
    PASTE YOUR HEX STRING HERE
================================ */
const HEX_INPUT = "";

/* ==============================
   MAIN
================================ */
async function decodeHex() {
  try {
    if (!HEX_INPUT) {
      throw new Error("Please provide HEX_INPUT");
    }

    // Load only required proto files
    const root = await protobuf.load([
      "Jeep_Proto/jeep_fota_command_message.proto",
      "Jeep_Proto/jeep_fota_command.proto",
      "Jeep_Proto/jeep_common.proto",
      "Jeep_Proto/timestamp.proto"
    ]);

    // Lookup message type
    const FotaCommandMessage = root.lookupType(
      "stla.cvip.jeep.fotaCommandMessage"
    );

    // Convert HEX → Buffer
    const buffer = Buffer.from(HEX_INPUT, "hex");

    // Decode protobuf
    const decoded = FotaCommandMessage.decode(buffer);

    // Convert to JSON
    const json = FotaCommandMessage.toObject(decoded, {
      longs: String,
      enums: String,
      defaults: true
    });

    console.log(JSON.stringify(json, null, 2));

  } catch (error) {
    console.error("DECODE ERROR:", error.message);
  }
}

decodeHex();
